import { useMemo } from 'react';
import { useIntl } from 'react-intl';
import { useParams } from 'react-router-dom';

import { TabInfo, TabsWithFilters } from 'components';
import { featureToggles } from 'config/featureToggle';
import { useFeatureToggle, useMultiplesFeatureToggles } from 'hooks';
import { createTab } from 'utils/tab';

import { INNOVATION_BASE_ROUTE, INNOVATION_PAGE_NAME } from '../constants';
import {
  INNOVATION_HUB_OVERVIEW_VISIBLE_FILTER_FIELDS,
  INNOVATION_HUB_PAGE_NAME,
} from '../InnovationHub/constants';
import { PerformanceAndBreakdown } from './tabs';
import { InnovationOverviewContent } from './tabs/Overview/InnovationOverviewContent';

const OVERVIEW_TAB_ID = 'overview';

export const Innovation: React.FC = () => {
  const { formatMessage } = useIntl();
  const { tab } = useParams<{ tab?: string }>();
  const [hubOverviewEnabled, hubOverviewLoading] = useFeatureToggle(
    featureToggles.pillar.innovation.submenus.innovationHub.id,
  );
  const isHubOverviewOn = Boolean(hubOverviewEnabled) && !hubOverviewLoading;
  const isOverviewTab = tab === OVERVIEW_TAB_ID || !tab;
  const { featuresListByToggleName: tabToggles, togglesReady } =
    useMultiplesFeatureToggles([
      featureToggles.pillar.innovation.submenus.innovation.tab.overview.id,
      featureToggles.pillar.innovation.submenus.innovation.tab
        .performanceAndBreakdown.id,
    ]);

  const tabs = useMemo<TabInfo[]>(
    () => [
      createTab(
        OVERVIEW_TAB_ID,
        'Overview',
        <InnovationOverviewContent
          isHubOverviewEnabled={isHubOverviewOn}
          dataTestId="tabpanel-overview"
        />,
        !tabToggles[
          featureToggles.pillar.innovation.submenus.innovation.tab.overview.id
        ],
      ),
      createTab(
        'performance-and-breakdown',
        'Performance & Breakdown',
        <PerformanceAndBreakdown dataTestId="tabpanel-performance-and-breakdown" />,
        !tabToggles[
          featureToggles.pillar.innovation.submenus.innovation.tab
            .performanceAndBreakdown.id
        ],
      ),
    ],
    [isHubOverviewOn, tabToggles],
  );

  const isHubOverviewFilter = isHubOverviewOn && isOverviewTab;

  if (!togglesReady) {
    return <></>;
  }

  return (
    <TabsWithFilters
      filter={
        isHubOverviewFilter
          ? {
              pageName: INNOVATION_HUB_PAGE_NAME,
              visibleFields: [...INNOVATION_HUB_OVERVIEW_VISIBLE_FILTER_FIELDS],
            }
          : {
              pageName: INNOVATION_PAGE_NAME,
              visibleFields: ['zone', 'country', 'time_frame'],
            }
      }
      tabConfig={{
        tabs,
        baseRoute: INNOVATION_BASE_ROUTE,
      }}
      dataTestId="innovation"
      breadcrumbsList={[
        {
          href: '/innovation',
          pageName: formatMessage({ id: 'Pillars.pageName.innovation' }),
        },
        {
          href: INNOVATION_BASE_ROUTE,
          pageName: formatMessage({ id: 'Sidebar.innovation' }),
        },
      ]}
      isResponsivePage={isHubOverviewFilter}
    />
  );
};
